55	final class InternalRouteStartupManager {
56	
57	    private static final Logger LOG = LoggerFactory.getLogger(InternalRouteStartupManager.class);
58	
59	    private final Lock lock = new ReentrantLock();
60	    private final ThreadLocal<Route> setupRoute = new ThreadLocal<>();
61	    private final CamelLogger routeLogger = new CamelLogger(LOG);
62	    private int defaultRouteStartupOrder = 1000;
63	
64	    /**
