72	     * Initializes the routes
73	     *
74	     * @param  routeServices the routes to initialize
75	     * @throws Exception     is thrown if error initializing routes
76	     */
77	    public void doInitRoutes(AbstractCamelContext camelContext, Map<String, RouteService> routeServices)
78	            throws Exception {
79	
80	        camelContext.startingRoutes(() -> {
81	            for (RouteService routeService : routeServices.values()) {
82	                StartupStep step = camelContext.getCamelContextExtension().getStartupStepRecorder().beginStep(Route.class,
83	                        routeService.getId(),
84	                        "Init Route");
85	                try {
86	                    LOG.debug("Initializing route id: {}", routeService.getId());
87	                    setupRoute.set(routeService.getRoute());
88	                    // initializing route is called doSetup as we do not want to change the service state on the RouteService
89	                    // so it can remain as stopped, when Camel is booting as this was the previous behavior - otherwise its state
90	                    // would be initialized
91	                    routeService.setUp();
92	                } finally {
93	                    setupRoute.remove();
94	                    camelContext.getCamelContextExtension().getStartupStepRecorder().endStep(step);
95	                }
96	            }
97	            return null;
98	        });
