101	    /**
102	     * Starts or resumes the routes
103	     *
104	     * @param  routeServices  the routes to start (will only start a route if its not already started)
105	     * @param  checkClash     whether to check for startup ordering clash
106	     * @param  startConsumer  whether the route consumer should be started. Can be used to warmup the route without
107	     *                        starting the consumer.
108	     * @param  resumeConsumer whether the route consumer should be resumed.
109	     * @param  addingRoutes   whether we are adding new routes
110	     * @throws Exception      is thrown if error starting routes
111	     */
112	    public void doStartOrResumeRoutes(
113	            AbstractCamelContext camelContext,
114	            Map<String, RouteService> routeServices, boolean checkClash, boolean startConsumer, boolean resumeConsumer,
115	            boolean addingRoutes)
116	            throws Exception {
117	        camelContext.startingRoutes(() -> {
118	            // filter out already started routes
119	            Map<String, RouteService> filtered = new LinkedHashMap<>();
120	            for (Map.Entry<String, RouteService> entry : routeServices.entrySet()) {
121	                final boolean startable = isStartable(entry);
122	
123	                if (startable) {
124	                    filtered.put(entry.getKey(), entry.getValue());
125	                }
126	            }
127	
128	            // the context is in last phase of staring, so lets start the routes
129	            safelyStartRouteServices(camelContext, checkClash, startConsumer, resumeConsumer, addingRoutes, filtered.values());
130	            return null;
131	        });
132	    }
