134	    private static boolean isStartable(Map.Entry<String, RouteService> entry) {
135	        boolean startable = false;
136	
137	        Consumer consumer = entry.getValue().getRoute().getConsumer();
138	        if (consumer instanceof SuspendableService suspendableService) {
139	            // consumer could be suspended, which is not reflected in
140	            // the BaseRouteService status
141	            startable = suspendableService.isSuspended();
142	        }
143	
144	        if (!startable && consumer instanceof StatefulService statefulService) {
145	            // consumer could be stopped, which is not reflected in the
146	            // BaseRouteService status
147	            startable = statefulService.getStatus().isStartable();
148	        } else if (!startable) {
149	            // no consumer so use state from route service
150	            startable = entry.getValue().getStatus().isStartable();
151	        }
152	        return startable;
153	    }
