240	    /**
241	     * @see #safelyStartRouteServices(AbstractCamelContext, boolean, boolean, boolean, boolean, Collection)
242	     */
243	    public void safelyStartRouteServices(
244	            AbstractCamelContext camelContext,
245	            boolean forceAutoStart, boolean checkClash, boolean startConsumer, boolean resumeConsumer, boolean addingRoutes,
246	            RouteService... routeServices)
247	            throws Exception {
248	        lock.lock();
249	        try {
250	            safelyStartRouteServices(camelContext, checkClash, startConsumer, resumeConsumer, addingRoutes,
251	                    Arrays.asList(routeServices));
252	        } finally {
253	            lock.unlock();
254	        }
255	    }
