273	    boolean doCheckStartupOrderClash(
274	            AbstractCamelContext camelContext, DefaultRouteStartupOrder answer, Map<Integer, DefaultRouteStartupOrder> inputs)
275	            throws FailedToStartRouteException {
276	        // check for clash by startupOrder id
277	        DefaultRouteStartupOrder other = inputs.get(answer.getStartupOrder());
278	        if (other != null && answer != other) {
279	            String otherId = other.getRoute().getId();
280	            throw new FailedToStartRouteException(
281	                    answer.getRoute().getId(), "Route startup order clash. Route " + otherId + " already has startupOrder "
282	                                               + answer
283	                                                       .getStartupOrder()
284	                                               + " configured which this route have as well. Please correct startupOrder to be unique among all your routes.");
285	        }
286	        // check in existing already started as well
287	        for (RouteStartupOrder order : camelContext.getCamelContextExtension().getRouteStartupOrder()) {
288	            String otherId = order.getRoute().getId();
289	            // skip clash check if it's the same route id, as it's the same
290	            // route (can happen when using suspend/resume)
291	            if (!answer.getRoute().getId().equals(otherId)
292	                    && answer.getStartupOrder() == order.getStartupOrder()) {
293	                throw new FailedToStartRouteException(
294	                        answer.getRoute().getId(), "Route startup order clash. Route " + otherId + " already has startupOrder "
295	                                                   + answer.getStartupOrder()
296	                                                   + " configured which this route have as well. Please correct startupOrder to be unique among all your routes.");
297	            }
298	        }
299	        return true;
300	    }
301	
302	    void doWarmUpRoutes(AbstractCamelContext camelContext, Map<Integer, DefaultRouteStartupOrder> inputs, boolean autoStartup)
303	            throws FailedToStartRouteException {
304	        // now prepare the routes by starting its services before we start the
305	        // input
306	        for (Map.Entry<Integer, DefaultRouteStartupOrder> entry : inputs.entrySet()) {
307	            // defer starting inputs till later as we want to prepare the routes
308	            // by starting
309	            // all their processors and child services etc.
310	            // then later we open the floods to Camel by starting the inputs
311	            // what this does is to ensure Camel is more robust on starting
312	            // routes as all routes
313	            // will then be prepared in time before we start inputs which will
314	            // consume messages to be routed
315	            RouteService routeService = entry.getValue().getRouteService();
316	            StartupStep step = camelContext.getCamelContextExtension().getStartupStepRecorder().beginStep(Route.class,
317	                    routeService.getId(),
318	                    "Warump Route");
319	            try {
320	                LOG.debug("Warming up route id: {} having autoStartup={}", routeService.getId(), autoStartup);
321	                setupRoute.set(routeService.getRoute());
322	                // ensure we setup before warmup
323	                routeService.setUp();
324	                routeService.warmUp();
325	            } finally {
326	                setupRoute.remove();
327	                camelContext.getCamelContextExtension().getStartupStepRecorder().endStep(step);
328	            }
329	        }
330	    }
331	
332	    void doResumeRouteConsumers(
333	            AbstractCamelContext camelContext, Map<Integer, DefaultRouteStartupOrder> inputs, boolean addingRoutes)
334	            throws Exception {
335	        doStartOrResumeRouteConsumers(camelContext, inputs, true, addingRoutes);
336	    }
337	
338	    void doStartRouteConsumers(
339	            AbstractCamelContext camelContext, Map<Integer, DefaultRouteStartupOrder> inputs, boolean addingRoutes)
340	            throws Exception {
341	        doStartOrResumeRouteConsumers(camelContext, inputs, false, addingRoutes);
342	    }
343	
344	    private LoggingLevel getRouteLoggerLogLevel(AbstractCamelContext camelContext) {
345	        return camelContext.getRouteController().getLoggingLevel();
346	    }
347	
348	    private void doStartOrResumeRouteConsumers(
349	            AbstractCamelContext camelContext,
350	            Map<Integer, DefaultRouteStartupOrder> inputs, boolean resumeOnly, boolean addingRoute)
351	            throws Exception {
352	        List<Endpoint> routeInputs = new ArrayList<>();
353	
354	        for (Map.Entry<Integer, DefaultRouteStartupOrder> entry : inputs.entrySet()) {
355	            Integer order = entry.getKey();
356	            Route route = entry.getValue().getRoute();
357	            RouteService routeService = entry.getValue().getRouteService();
358	
359	            // if we are starting camel, then skip routes which are configured
360	            // to not be auto started
361	            boolean autoStartup = routeService.isAutoStartup();
362	            if (addingRoute && !autoStartup) {
363	                routeLogger.log(
364	                        "Skipping starting of route " + routeService.getId() + " as it's configured with autoStartup=false",
365	                        getRouteLoggerLogLevel(camelContext));
366	                continue;
367	            }
368	
369	            StartupStep step = camelContext.getCamelContextExtension().getStartupStepRecorder().beginStep(Route.class,
370	                    route.getRouteId(),
371	                    "Start Route");
372	
373	            // do some preparation before starting the consumer on the route
374	            Consumer consumer = routeService.getInput();
375	            if (consumer != null) {
376	                Endpoint endpoint = consumer.getEndpoint();
377	
378	                // check multiple consumer violation, with the other routes to be started
379	                if (!doCheckMultipleConsumerSupportClash(endpoint, routeInputs)) {
380	                    throw new FailedToStartRouteException(
381	                            routeService.getId(), "Multiple consumers for the same endpoint is not allowed: " + endpoint);
382	                }
383	
384	                // check for multiple consumer violations with existing routes
385	                // which have already been started, or is currently starting
386	                List<Endpoint> existingEndpoints = new ArrayList<>();
387	                for (Route existingRoute : camelContext.getRoutes()) {
388	                    if (route.getId().equals(existingRoute.getId())) {
389	                        // skip ourselves
390	                        continue;
391	                    }
392	                    Endpoint existing = existingRoute.getEndpoint();
393	                    ServiceStatus status = camelContext.getRouteStatus(existingRoute.getId());
394	                    if (status != null && (status.isStarted() || status.isStarting())) {
395	                        existingEndpoints.add(existing);
396	                    }
397	                }
398	                if (!doCheckMultipleConsumerSupportClash(endpoint, existingEndpoints)) {
399	                    throw new FailedToStartRouteException(
400	                            routeService.getId(), "Multiple consumers for the same endpoint is not allowed: " + endpoint);
401	                }
402	
403	                // start the consumer on the route
404	                LOG.debug("Route: {} >>> {}", route.getId(), route);
405	                if (resumeOnly) {
406	                    LOG.debug("Resuming consumer (order: {}) on route: {}", order, route.getId());
407	                } else {
408	                    LOG.debug("Starting consumer (order: {}) on route: {}", order, route.getId());
409	                }
410	
411	                if (resumeOnly && route.supportsSuspension()) {
412	                    // if we are resuming and the route can be resumed
413	                    ServiceHelper.resumeService(consumer);
414	                    // use basic endpoint uri to not log verbose details or potential sensitive data
415	                    String uri = endpoint.getEndpointBaseUri();
416	                    uri = URISupport.sanitizeUri(uri);
417	                    routeLogger.log("Route: " + route.getId() + " resumed and consuming from: " + uri,
418	                            getRouteLoggerLogLevel(camelContext));
419	                } else {
420	                    // when starting we should invoke the lifecycle strategies
421	                    for (LifecycleStrategy strategy : camelContext.getLifecycleStrategies()) {
422	                        strategy.onServiceAdd(camelContext.getCamelContextReference(), consumer, route);
423	                    }
424	                    try {
425	                        camelContext.startService(consumer);
426	                        route.getProperties().remove("route.start.exception");
427	                    } catch (Exception e) {
428	                        route.getProperties().put("route.start.exception", e);
429	                        throw e;
430	                    }
431	
432	                    // use basic endpoint uri to not log verbose details or potential sensitive data
433	                    String uri = endpoint.getEndpointBaseUri();
434	                    uri = URISupport.sanitizeUri(uri);
435	                    routeLogger.log("Route: " + route.getId() + " started and consuming from: " + uri,
436	                            getRouteLoggerLogLevel(camelContext));
437	                }
438	
439	                routeInputs.add(endpoint);
440	
441	                // add to the order which they was started, so we know how to
442	                // stop them in reverse order
443	                // but only add if we haven't already registered it before (we
444	                // dont want to double add when restarting)
445	                boolean found = false;
446	                for (RouteStartupOrder other : camelContext.getCamelContextExtension().getRouteStartupOrder()) {
447	                    if (other.getRoute().getId().equals(route.getId())) {
448	                        found = true;
449	                        break;
450	                    }
451	                }
452	                if (!found) {
453	                    camelContext.getCamelContextExtension().getRouteStartupOrder().add(entry.getValue());
454	                }
455	            }
456	
457	            if (resumeOnly) {
458	                routeService.resume();
459	            } else {
460	                // and start the route service (no need to start children as
461	                // they are already warmed up)
462	                try {
463	                    routeService.start();
464	                    route.getProperties().remove("route.start.exception");
465	                } catch (Exception e) {
466	                    route.getProperties().put("route.start.exception", e);
467	                    throw e;
468	                }
469	            }
470	
471	            camelContext.getCamelContextExtension().getStartupStepRecorder().endStep(step);
472	        }
473	    }
474	
475	    private boolean doCheckMultipleConsumerSupportClash(Endpoint endpoint, List<Endpoint> routeInputs) {
476	        // is multiple consumers supported
477	        boolean multipleConsumersSupported = false;
478	        if (endpoint instanceof MultipleConsumersSupport consumersSupport) {
479	            multipleConsumersSupported = consumersSupport.isMultipleConsumersSupported();
480	        }
481	
482	        if (multipleConsumersSupported) {
483	            // multiple consumer allowed, so return true
484	            return true;
485	        }
486	
487	        // check in progress list
488	        if (routeInputs.contains(endpoint)) {
489	            return false;
490	        }
491	
492	        return true;
493	    }
494	
495	    int incrementRouteStartupOrder() {
496	        return defaultRouteStartupOrder++;
497	    }
498	
499	}
